-- 3. Update pr_photo in live nodes
UPDATE `nodes` n
JOIN `_migration_file_managed` m 
  ON m.fid = CAST(JSON_UNQUOTE(JSON_EXTRACT(n.fields_data, '$.pr_photo')) AS UNSIGNED)
SET n.fields_data = JSON_SET(n.fields_data, '$.pr_photo', m.file_url)
WHERE JSON_UNQUOTE(JSON_EXTRACT(n.fields_data, '$.pr_photo')) REGEXP '^[0-9]+$';

-- 4. Update pr_photo in node revisions
UPDATE `node_revisions` nr
JOIN `_migration_file_managed` m 
  ON m.fid = CAST(JSON_UNQUOTE(JSON_EXTRACT(nr.fields_data, '$.pr_photo')) AS UNSIGNED)
SET nr.fields_data = JSON_SET(nr.fields_data, '$.pr_photo', m.file_url)
WHERE JSON_UNQUOTE(JSON_EXTRACT(nr.fields_data, '$.pr_photo')) REGEXP '^[0-9]+$';

